ReplacementChunks.ReplacementContent:
 {crewGroups.map((g) => (
  <div
    key={g.name}
    className="w-full flex items-center justify-between gap-1 pl-1 pr-0.5 py-0.5 rounded hover:bg-white/[0.04] transition-all group/item"
  >
    <button
      type="button"
      onClick={(e) => {
        e.stopPropagation();
        handleAddGroupToDay(day.dateStr, g);
      }}
      className="flex-1 text-left rounded-md hover:text-emerald-400 text-[9px] font-bold transition-all border-none bg-transparent cursor-pointer flex items-center justify-between py-0.5"
    >
      <span>👥 {g.name}</span>
      <span className="text-[7.5px] text-white/35 font-bold mr-1">{g.memberIds.length} crew</span>
    </button>

    <button
      type="button"
      title="Delete Saved Group"
      onClick={(e) => {
        e.stopPropagation();
        if (confirm(`Are you sure you want to delete the group "${g.name}"?`)) {
          deleteGroup(g.name);
        }
      }}
      className="w-3.5 h-3.5 rounded hover:bg-red-500/20 text-white/30 hover:text-red-400 flex items-center justify-center text-[7.5px] font-bold border-none bg-transparent cursor-pointer transition-colors"
    >
      ✕
    </button>
  </div>
))}

